import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  describe('input validation', () => {
    it('returns a ToolResponse naming the missing required field without calling the executor', async () => {
      const registry = new ToolRegistry();
      let executorCalled = false;
      registry.register(
        {
          name: 'greet',
          description: 'greet someone',
          inputSchema: {
            type: 'object',
            properties: {name: {type: 'string'}},
            required: ['name'],
          },
        },
        async () => {
          executorCalled = true;
          return 'hello';
        }
      );

      const response = await registry.execute('greet', {});

      expect(executorCalled).toBe(false);
      expect(response.result).toMatch(/name/);
      expect(response.result).toMatch(/required/i);
    });
  });
});

